// CDLRISEFALL3METHODSOpen opens a live [CDLRISEFALL3METHODSStream] on a warm-up
// history, oldest bar first, and returns it with its value at the last history
// bar, the value [Core.CDLRISEFALL3METHODS] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLRISEFALL3METHODSLookback] bars, [OutOfRangeEndIndex] for one longer
// than [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDLRISEFALL3METHODSOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLRISEFALL3METHODSStream, int32, error) {
	sp, err := c.cdlrisefall3methodsOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLRISEFALL3METHODSOpenAndFill opens a stream as
// [Core.CDLRISEFALL3METHODSOpen] does and also writes the outputs over the
// whole history, as [Core.CDLRISEFALL3METHODS] writes them for bars 0 through
// len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLRISEFALL3METHODSLookback]
// values and share no memory with an input or another output.
//
// The errors are those of [Core.CDLRISEFALL3METHODSOpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLRISEFALL3METHODSOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLRISEFALL3METHODSStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlrisefall3methodsLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlrisefall3methodsOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
